import kurlar from './kurlar.json' with { type: 'json' }

export function tlKarsiligi(tutar, birim) {
  throw new Error('Henüz yazılmadı')
}

import test from 'node:test'
import assert from 'node:assert/strict'
import kurlar from './kurlar.json' with { type: 'json' }
import { tlKarsiligi } from './doviz.js'

test('dolar tutarı güncel kurla çevrilir', () => {
  assert.equal(tlKarsiligi(100, 'USD'), Math.round(100 * kurlar.USD * 100) / 100)
})

mesajlar.reasoning_content:
Testler `doviz.test.js` içinde ve `kurlar` objesinden `kurlar.USD`'yi bekliyor. Şimdi `kurlar.json` dosyasını oluşturalım. Basit bir USD kuru ile başlayalım, sonra testleri çalıştırıp ayarlayalım.

`kurlar.json` için:
```json
{
  "USD": 32.50
}
```

Sonra `doviz.js`'yi güncelleyeyim:
```javascript
import kurlar from './kurlar.json' with { type: 'json' }

export function tlKarsiligi(tutar, birim) {
  return Math.round(tutar * kurlar[birim] * 100) / 100
}
```

Testlerde `birim` parametresi 'USD' olarak geçiyor, yani `kurlar.USD` kullanılmış. Ama ben `kurlar[birim]` kullanırsam esnek olur.

Önce `kurlar.json`'u yazalım.

